import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from 'react'
import { BrowserRouter, Link, Navigate, Route, Routes, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import { ArrowLeft, ArrowRight, Bell, BusFront, CalendarDays, Check, ChevronDown, CircleUserRound, Clock3, Download, FileText, Filter, Home, Languages, LayoutDashboard, ListFilter, LogOut, Menu, MoreHorizontal, Phone, Plus, Search, Settings2, ShieldAlert, ShieldCheck, Ticket, UsersRound, X, Zap } from 'lucide-react'
import { useAuth } from '@/hooks/useAuth'
import { usePreferences, type Language } from '@/i18n'
import { previewMode, listActiveStations, listDepartureTimes, getSubscription, getBookingHours, adminUpdateBookingHours, listAdminProfiles, adminUpdateAdminStatus, listBookings, listStationBookingsAdmin, listNotifications, createBookingBatch, createBookingChangeRequest, cancelBooking, markNotificationRead, updateOwnProfile, getDashboardStats, adminUpdateProfileStatus, adminUpdateBookingStatus, adminCreateStation, adminCreateDepartureTime, listProfilesAdmin, listSubscriptionsAdmin, listBookingChangeRequestsAdmin, adminReviewBookingChangeRequest, adminToggleStation, adminRenameStation, adminToggleDepartureTime, adminRenameDepartureTime, adminUpdateSubscription, listStationsAdmin, listDepartureTimesAdmin, adminReorderStation, adminReorderDepartureTime, listSecurityEventsAdmin, adminResolveSecurityEvent } from '@/lib/api'
import type { AppNotification, Booking, BookingChangeRequest, BookingHours, BookingStatus, DashboardStats, DepartureTime, Profile, SecurityEvent, Station, Subscription } from '@/types/domain'
import { supabaseConfigured } from '@/lib/supabase'

const cx = (...classes: Array<string | false | undefined>) => classes.filter(Boolean).join(' ')
const todayISO = () => new Date().toISOString().slice(0, 10)
const formatDate = (value: string, language: Language) => new Intl.DateTimeFormat(language === 'ar' ? 'ar-EG' : 'en-GB', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(`${value}T00:00:00`))
const daysLeft = (endDate?: string | null) => endDate ? Math.max(0, Math.ceil((new Date(`${endDate}T23:59:59`).getTime() - Date.now()) / 86400000)) : 0
const statusLabel = (t: (key: any) => string, value: string) => {
  const labels: Record<string, string> = { confirmed: t('confirmed'), cancelled: t('cancelled'), boarded: t('boarded'), no_show: t('no_show'), active: t('active'), pending: t('pending'), approved: t('approved'), rejected: t('rejected'), suspended: t('suspended'), expired: t('expired') }
  return labels[value] || value
}
const timeToMinutes = (value: string) => { const [hours, minutes] = value.slice(0, 5).split(':').map(Number); return (hours || 0) * 60 + (minutes || 0) }
const isBookingOpen = (hours: BookingHours) => { const now = new Date(); const current = now.getHours() * 60 + now.getMinutes(); const open = timeToMinutes(hours.openTime); const close = timeToMinutes(hours.closeTime); return open < close ? current >= open && current < close : open > close ? current >= open || current < close : false }
const formatClock = (value: string, language: Language) => new Intl.DateTimeFormat(language === 'ar' ? 'ar-EG' : 'en-GB', { hour: 'numeric', minute: '2-digit' }).format(new Date(`1970-01-01T${value.slice(0, 5)}:00`))

function Logo({ compact = false }: { compact?: boolean }) { return <div className={cx('flex items-center gap-2.5', compact ? 'min-w-0' : '')}><img src="/branding/saidy-mark.svg" alt="El Saidy Travel" className={compact ? 'h-9 w-10 shrink-0 object-contain' : 'h-11 w-12 shrink-0 object-contain'} /><span className={cx('font-black tracking-tight text-ink ', compact ? 'sr-only' : 'text-lg')}>El Saidy Travel</span></div> }
function Button({ children, variant = 'primary', className, ...props }: { children: ReactNode; variant?: 'primary' | 'ghost' | 'soft' | 'danger' | 'outline'; className?: string } & React.ButtonHTMLAttributes<HTMLButtonElement>) {
  const styles = { primary: 'bg-ink text-white hover:bg-slate-800  ', ghost: 'text-slate-500 hover:bg-slate-100 hover:text-ink  ', soft: 'bg-sky text-ink hover:bg-teal-100  ', danger: 'bg-rose/10 text-rose hover:bg-rose/20', outline: 'border border-slate-200 bg-white text-ink hover:border-route   ' }
  return <button className={cx('inline-flex min-h-11 items-center justify-center gap-2 rounded-2xl px-4 text-sm font-bold transition active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50', styles[variant], className)} {...props}>{children}</button>
}
function IconButton({ label, children, ...props }: { label: string; children: ReactNode } & React.ButtonHTMLAttributes<HTMLButtonElement>) { return <button aria-label={label} title={label} className="grid h-10 w-10 place-items-center rounded-2xl text-slate-500 transition hover:bg-slate-100 hover:text-ink  " {...props}>{children}</button> }
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <section className={cx('ios-card rounded-[1.5rem] border border-slate-200/80 bg-white p-5 shadow-soft  ', className)}>{children}</section> }
function Badge({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'success' | 'warning' | 'danger' | 'info' }) { const colors = { neutral: 'bg-slate-100 text-slate-600  ', success: 'bg-emerald-50 text-emerald-700  ', warning: 'bg-amber-50 text-amber-700  ', danger: 'bg-rose-50 text-rose ', info: 'bg-sky text-ink  ' }; return <span className={cx('inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-bold', colors[tone])}>{children}</span> }
function StatusBadge({ value, t }: { value: string; t: (key: any) => string }) { const tone = ['confirmed', 'approved', 'active', 'boarded'].includes(value) ? 'success' : ['pending', 'no_show'].includes(value) ? 'warning' : ['rejected', 'suspended', 'expired', 'cancelled'].includes(value) ? 'danger' : 'neutral'; return <Badge tone={tone as any}>{statusLabel(t, value)}</Badge> }
function EmptyState({ icon: Icon = FileText, title, text }: { icon?: any; title: string; text?: string }) { return <div className="route-stripes grid min-h-40 place-items-center rounded-3xl border border-dashed border-slate-200 p-6 text-center "><div><div className="mx-auto mb-3 grid h-12 w-12 place-items-center rounded-2xl bg-sky text-ink  "><Icon size={22} /></div><p className="font-bold text-ink ">{title}</p>{text && <p className="mt-1 text-sm text-slate-500">{text}</p>}</div></div> }
function LoadingState() { return <div className="space-y-4"><div className="h-28 animate-pulse rounded-3xl bg-slate-200 " /><div className="grid gap-4 md:grid-cols-3"><div className="h-24 animate-pulse rounded-3xl bg-slate-200 " /><div className="h-24 animate-pulse rounded-3xl bg-slate-200 " /><div className="h-24 animate-pulse rounded-3xl bg-slate-200 " /></div></div> }

type AuthMode = 'login' | 'register' | 'forgot'

function AuthPage({ mode, setMode, onSignIn, onSignUp, onResetPassword, isPreview, t, language, setLanguage }: { mode: AuthMode; setMode: (mode: AuthMode) => void; onSignIn: (email: string, password: string) => Promise<void>; onSignUp: (values: any) => Promise<any>; onResetPassword: (email: string) => Promise<void>; isPreview: boolean; t: any; language: Language; setLanguage: (l: Language) => void }) {
  const [email, setEmail] = useState(isPreview ? 'ahmed@example.com' : '')
  const [password, setPassword] = useState(isPreview ? 'password123' : '')
  const [fullName, setFullName] = useState('')
  const [studentId, setStudentId] = useState('')
  const [phone, setPhone] = useState('')
  const [university, setUniversity] = useState('جامعة الجلالة')
  const [stationId, setStationId] = useState('')
  const [preferredWeekdays, setPreferredWeekdays] = useState<number[]>([0, 1, 2, 3, 4, 5, 6])
  const [stations, setStations] = useState<Station[]>([])
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const navigate = useNavigate()
  const weekdayOptions = [[0, t('sun')], [1, t('mon')], [2, t('tue')], [3, t('wed')], [4, t('thu')], [5, t('fri')], [6, t('sat')]] as const
  useEffect(() => { void listActiveStations().then(setStations).catch(() => undefined) }, [])
  async function submit(event: FormEvent) {
    event.preventDefault(); setError(''); setBusy(true)
    try {
      if (mode === 'forgot') { await onResetPassword(email); setError(t('resetSent')); return }
      if (mode === 'login') { await onSignIn(email, password); navigate('/app') }
      else {
        if (!preferredWeekdays.length) { setError(t('required')); return }
        await onSignUp({ email, password, fullName, studentId, phone, university, stationId, preferredWeekdays }); setMode('login'); navigate('/auth/login'); setError('تم إنشاء الحساب. يمكنك تسجيل الدخول الآن.')
      }
    } catch (err: any) { setError(err?.message === 'SUPABASE_NOT_CONFIGURED' ? t('configuredRequired') : err?.message === 'AUTH_RATE_LIMIT' ? t('authRateLimited') : (err?.message || t('genericError'))) } finally { setBusy(false) }
  }
  function choosePreviewRole(role: 'student' | 'admin') { localStorage.setItem('suezbus-preview-role', role); navigate(role === 'admin' ? '/admin' : '/app') }
  function switchMode(next: AuthMode) { setMode(next); navigate(next === 'forgot' ? '/auth/forgot-password' : next === 'register' ? '/auth/register' : '/auth/login') }
  const title = mode === 'forgot' ? t('forgotPassword') : mode === 'login' ? t('login') : t('register')
  return <div className="ios-page min-h-screen px-4 py-5 sm:px-6"><div className="mx-auto flex max-w-md items-center justify-between"><Logo /><div className="flex items-center gap-1"><IconButton label={t('language')} onClick={() => setLanguage(language === 'ar' ? 'en' : 'ar')}><Languages size={18} /></IconButton></div></div><main className="mx-auto max-w-md py-8 sm:py-14"><Card className="ios-card p-6 sm:p-8"><div className="mb-7 text-center"><p className="text-xs font-black uppercase tracking-[.18em] text-slate-400">El Saidy Travel</p><h1 className="mt-3 text-3xl font-black text-ink ">{title}</h1>{mode === 'register' && <p className="mt-2 text-sm text-slate-500">{t('scheduleHint')}</p>}</div>{error && <div className="mb-5 rounded-2xl bg-rose-50 p-3 text-sm font-bold text-rose">{error}</div>}<form onSubmit={submit} className="space-y-4">{mode === 'register' && <><Field label={t('fullName')} value={fullName} onChange={setFullName} required /><div className="grid gap-4 sm:grid-cols-2"><Field label={t('studentId')} value={studentId} onChange={setStudentId} required /><Field label={t('phone')} value={phone} onChange={setPhone} required inputMode="tel" /></div><Field label={t('university')} value={university} onChange={setUniversity} required /><SelectField label={t('defaultStation')} value={stationId} onChange={setStationId} options={stations.map((s) => [s.id, s.name_ar])} required /><div><p className="mb-2 text-sm font-bold text-slate-600 ">{t('preferredWeekdays')}</p><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{weekdayOptions.map(([day, label]) => <button type="button" key={day} onClick={() => setPreferredWeekdays((days) => days.includes(day) ? days.filter((item) => item !== day) : [...days, day].sort())} className={cx('ios-chip rounded-2xl px-3 py-3 text-sm font-bold transition', preferredWeekdays.includes(day) ? 'ios-chip-active' : 'bg-slate-100 text-slate-500 ')}>{label}</button>)}</div></div></>}<Field label={t('email')} type="email" value={email} onChange={setEmail} required dir="ltr" />{mode !== 'forgot' && <Field label={t('password')} type="password" value={password} onChange={setPassword} required dir="ltr" />}{mode === 'forgot' ? <Button className="ios-primary w-full" disabled={busy}>{busy ? t('loading') : t('forgotPassword')} <ArrowLeft size={17} /></Button> : <Button className="ios-primary w-full" disabled={busy}>{busy ? t('loading') : mode === 'login' ? t('signIn') : t('createAccount')} <ArrowLeft size={17} /></Button>}</form><div className="mt-6 text-center text-sm text-slate-500">{mode === 'forgot' ? <button className="font-bold text-route" onClick={() => switchMode('login')}>{t('backToLogin')}</button> : mode === 'login' ? <><button className="font-bold text-route" onClick={() => switchMode('forgot')}>{t('forgotPassword')}</button><span className="mx-2">·</span>{t('noAccount')} <button className="font-bold text-route" onClick={() => switchMode('register')}>{t('register')}</button></> : <>{t('haveAccount')} <button className="font-bold text-route" onClick={() => switchMode('login')}>{t('login')}</button></>}</div>{isPreview && mode === 'login' && <div className="mt-6 grid gap-2 border-t border-slate-100 pt-5  sm:grid-cols-2"><Button type="button" variant="soft" onClick={() => choosePreviewRole('student')}>Student demo</Button><Button type="button" variant="outline" onClick={() => choosePreviewRole('admin')}>Admin demo</Button></div>}</Card><p className="mt-6 text-center text-xs font-semibold text-slate-400">{t('footer')}</p></main></div>
}

function Field({ label, value, onChange, type = 'text', required = false, dir, placeholder, inputMode, disabled = false }: { label: string; value: string; onChange: (value: string) => void; type?: string; required?: boolean; dir?: 'ltr' | 'rtl'; placeholder?: string; inputMode?: any; disabled?: boolean }) { return <label className="block"><span className="mb-1.5 block text-sm font-bold text-slate-600 ">{label}</span><input className="h-12 w-full rounded-2xl border border-slate-200 bg-white px-4 text-sm text-ink outline-none transition placeholder:text-slate-400 focus:border-route focus:ring-4 focus:ring-route/10 disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-400    " value={value} onChange={(e) => onChange(e.target.value)} type={type} required={required} dir={dir} placeholder={placeholder} inputMode={inputMode} disabled={disabled} /></label> }
function SelectField({ label, value, onChange, options, required = false }: { label: string; value: string; onChange: (value: string) => void; options: string[][]; required?: boolean }) { return <label className="block"><span className="mb-1.5 block text-sm font-bold text-slate-600 ">{label}</span><select className="h-12 w-full rounded-2xl border border-slate-200 bg-white px-4 text-sm text-ink outline-none focus:border-route focus:ring-4 focus:ring-route/10   " value={value} onChange={(e) => onChange(e.target.value)} required={required}><option value="">—</option>{options.map(([id, label]) => <option value={id} key={id}>{label}</option>)}</select></label> }

function Shell({ profile, children, t, language, setLanguage, signOut, unreadCount }: { profile: Profile; children: ReactNode; t: any; language: Language; setLanguage: (l: Language) => void; signOut: () => Promise<void>; unreadCount: number }) {
  const location = useLocation(); const navigate = useNavigate(); const [mobileNav, setMobileNav] = useState(false); const admin = profile.role === 'admin' || profile.role === 'staff'
  const studentItems = [{ to: '/app', label: t('dashboard'), icon: Home }, { to: '/app/bookings/new', label: t('newBooking'), icon: Plus }, { to: '/app/bookings', label: t('bookings'), icon: Ticket }, { to: '/app/profile', label: t('profile'), icon: CircleUserRound }]
  const adminItems = [{ to: '/admin', label: t('overview'), icon: LayoutDashboard }, { to: '/admin/students', label: t('students'), icon: UsersRound }, { to: '/admin/bookings', label: t('adminBookings'), icon: ListFilter }, { to: '/admin/requests', label: t('scheduleRequests'), icon: Clock3 }, { to: '/admin/security', label: t('securityAlerts'), icon: ShieldAlert }, { to: '/admin/subscriptions', label: t('subscriptions'), icon: CalendarDays }, { to: '/admin/stations', label: t('stations'), icon: MapPinIcon }, { to: '/admin/departures', label: t('departureTimes'), icon: Clock3 }, { to: '/admin/booking-hours', label: t('bookingHours'), icon: Clock3 }, { to: '/admin/admins', label: t('adminAccounts'), icon: UsersRound }]
  const items = admin ? adminItems : studentItems
  async function logout() { localStorage.removeItem('suezbus-preview-role'); await signOut(); navigate('/auth/login') }
  return <div className="ios-shell min-h-screen"><aside className="fixed inset-y-0 start-0 z-30 hidden w-72 flex-col border-e border-slate-200 bg-white px-5 py-6   lg:flex"><Logo /><div className="mt-10 flex-1 space-y-1">{items.map(({ to, label, icon: Icon }) => <NavItem key={to} to={to} label={label} icon={<Icon size={18} />} active={location.pathname === to} badge={label === t('notifications') ? unreadCount : undefined} />)}</div><div className="space-y-2 border-t border-slate-100 pt-5 "><div className="flex items-center gap-3 rounded-2xl bg-white/70 p-3 "><div className="grid h-10 w-10 place-items-center rounded-full bg-route text-sm font-black text-white">{profile.full_name.slice(0, 1)}</div><div className="min-w-0"><p className="truncate text-sm font-bold text-ink ">{profile.full_name}</p><p className="text-xs text-slate-400">{admin ? t('admin') : profile.student_id}</p></div></div><Button variant="ghost" className="w-full justify-start" onClick={logout}><LogOut size={17} /> {t('logout')}</Button></div></aside><div className="lg:ps-72"><header className="safe-top sticky top-0 z-20 border-b border-slate-200 bg-white px-4 pb-3   sm:px-6 lg:px-10"><div className="mx-auto flex max-w-7xl items-center justify-between"><div className="flex items-center gap-3 lg:hidden"><IconButton label="menu" onClick={() => setMobileNav(!mobileNav)}><Menu size={21} /></IconButton><Logo compact /></div><div className="hidden lg:block"><p className="text-sm font-black text-slate-500">{admin ? t('dashboard') : t('appName')}</p></div><div className="flex items-center gap-1"><button onClick={() => setLanguage(language === 'ar' ? 'en' : 'ar')} className="hidden items-center gap-1 rounded-xl px-2 py-2 text-xs font-bold text-slate-500 hover:bg-slate-100  sm:flex"><Languages size={15} /> {language === 'ar' ? 'English' : 'العربية'}</button><Link to={admin ? '/admin' : '/app/notifications'} className="relative grid h-10 w-10 place-items-center rounded-2xl text-slate-500 hover:bg-slate-100 "><Bell size={18} />{unreadCount > 0 && <span className="absolute end-1 top-1 grid h-4 min-w-4 place-items-center rounded-full bg-rose px-1 text-[9px] font-black text-white">{unreadCount}</span>}</Link></div></div>{mobileNav && <><button aria-label={t('close')} className="fixed inset-0 z-30 bg-black/20 lg:hidden" onClick={() => setMobileNav(false)} /><div className="mobile-nav-panel mobile-bottom-safe fixed inset-x-3 bottom-3 z-40 grid gap-1 rounded-[2rem] border border-slate-200 bg-white p-3 shadow-lift   lg:hidden">{items.map(({ to, label, icon: Icon }) => <NavItem key={to} to={to} label={label} icon={<Icon size={19} />} active={location.pathname === to} onClick={() => setMobileNav(false)} />)}<button className="mobile-nav-item flex items-center gap-3 rounded-2xl px-3 py-3 text-sm font-bold text-rose transition hover:bg-rose/10" onClick={logout}><LogOut size={19} /> {t('logout')}</button></div></>}</header><main className="mx-auto max-w-7xl p-4 pb-24 sm:p-6 lg:p-10">{children}</main><footer className="no-print px-4 pb-8 text-center text-xs font-semibold text-slate-400 lg:ps-72">{t('footer')}</footer></div></div>
}
function NavItem({ to, label, icon, active, badge, onClick }: { to: string; label: string; icon: ReactNode; active?: boolean; badge?: number; onClick?: () => void }) { return <Link to={to} onClick={onClick} className={cx('mobile-nav-item flex items-center gap-3 rounded-2xl px-3 py-3 text-sm font-bold transition', active ? 'bg-ink text-white shadow-soft ' : 'text-slate-500 hover:bg-slate-100 hover:text-ink  ')}><span>{icon}</span><span className="flex-1">{label}</span>{badge ? <span className={cx('grid h-5 min-w-5 place-items-center rounded-full px-1 text-[10px]', active ? 'bg-white/20 text-white' : 'bg-rose text-white')}>{badge}</span> : null}</Link> }
function MapPinIcon({ size = 18 }: { size?: number }) { return <span style={{ fontSize: size * .8 }}>⌖</span> }

function PageTitle({ eyebrow, title, text, action }: { eyebrow?: string; title: string; text?: string; action?: ReactNode }) { return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <p className="mb-2 text-xs font-black uppercase tracking-[.18em] text-route">{eyebrow}</p>}<h1 className="text-2xl font-black tracking-tight text-ink  sm:text-3xl">{title}</h1>{text && <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">{text}</p>}</div>{action}</div> }
function StatCard({ icon: Icon, label, value, hint, tone = 'route', to }: { icon: any; label: string; value: string | number; hint?: string; tone?: 'route' | 'amber' | 'rose' | 'ink'; to?: string }) { const bg = { route: 'bg-sky text-ink  ', amber: 'bg-amber-50 text-amber-700  ', rose: 'bg-rose-50 text-rose ', ink: 'bg-ink text-white' }; const content = <Card className={cx('relative overflow-hidden', to && 'cursor-pointer transition hover:-translate-y-0.5')}><div className="flex items-start justify-between"><div><p className="text-sm font-bold text-slate-500">{label}</p><p className="mt-3 text-3xl font-black tabular text-ink ">{value}</p>{hint && <p className="mt-1 text-xs font-semibold text-slate-400">{hint}</p>}</div><div className={cx('grid h-11 w-11 place-items-center rounded-2xl', bg[tone])}><Icon size={20} /></div></div></Card>; return to ? <Link to={to}>{content}</Link> : content }

function BookingHoursBanner({ hours, t, language }: { hours: BookingHours; t: any; language: Language }) {
  const open = isBookingOpen(hours)
  return <div className={cx('mb-5 flex items-start gap-3 rounded-2xl p-4 text-sm font-bold', open ? 'bg-emerald-50 text-emerald-800' : 'bg-amber-50 text-amber-900')}><Clock3 className="mt-0.5 shrink-0" size={19} /><div><p>{open ? t('bookingOpen') : t('bookingClosed')}</p><p className="mt-1 text-xs font-semibold opacity-80">{hours.openTime} – {hours.closeTime}{!open && ` · ${t('bookingClosedNext')} ${formatClock(hours.openTime, language)}`}</p></div></div>
}

function StudentDashboard({ profile, t, language }: { profile: Profile; t: any; language: Language }) {
  const [subscription, setSubscription] = useState<Subscription | null>(null); const [bookings, setBookings] = useState<Booking[]>([]); const [notifications, setNotifications] = useState<AppNotification[]>([]); const [hours, setHours] = useState<BookingHours>({ openTime: '08:00', closeTime: '22:00' }); const [loading, setLoading] = useState(true)
  useEffect(() => { void Promise.all([getSubscription(profile.id), listBookings(profile.id), listNotifications(profile.id), getBookingHours()]).then(([sub, b, n, bookingHours]) => { setSubscription(sub); setBookings(b); setNotifications(n); setHours(bookingHours) }).finally(() => setLoading(false)) }, [profile.id])
  if (loading) return <LoadingState />
  const remaining = daysLeft(subscription?.end_date); const subProgress = subscription ? Math.max(0, Math.min(100, Math.round(((new Date().getTime() - new Date(`${subscription.start_date}T00:00:00`).getTime()) / (new Date(`${subscription.end_date}T23:59:59`).getTime() - new Date(`${subscription.start_date}T00:00:00`).getTime())) * 100))) : 0
  const blocked = profile.account_status === 'suspended' || !subscription || subscription.status !== 'active' || remaining === 0 || !isBookingOpen(hours)
  return <div className="animate-rise"><PageTitle eyebrow={profile.role === 'admin' ? t('admin') : t('overview')} title={`${t(new Date().getHours() < 12 ? 'goodMorning' : 'goodEvening')}، ${profile.full_name.split(' ')[0]}`} action={!blocked && <Link to="/app/bookings/new"><Button><Plus size={18} /> {t('newBooking')}</Button></Link>} /><BookingHoursBanner hours={hours} t={t} language={language} />{profile.account_status === 'suspended' && <Card className="mb-5 border-amber/30 bg-amber-50/70 "><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 text-amber-600" size={22} /><div><h3 className="font-black text-ink ">{t('accountStatus')}: <StatusBadge value={profile.account_status} t={t} /></h3><p className="mt-2 text-sm text-slate-600 ">{t('suspendedMessage')}</p></div></div></Card>}
    <div className="grid gap-4 md:grid-cols-3"><Card className="md:col-span-2 overflow-hidden bg-ink text-white"><div className="flex flex-col justify-between gap-8 sm:flex-row"><div><Badge tone="info"><Ticket size={14} /> {t('subscription')}</Badge><h2 className="mt-5 text-2xl font-black">{subscription ? `${remaining} ${t('remainingDays')}` : t('noSubscription')}</h2><p className="mt-2 text-sm text-slate-300">{subscription ? `${t('ends')} ${formatDate(subscription.end_date, language)}` : t('bookBlocked')}</p></div><div className="route-stripes rounded-3xl p-4 sm:w-48"><div className="flex items-center gap-2 text-xs text-slate-300"><span>{t('starts')}</span><span className="h-px flex-1 bg-white/20" /><span>{t('ends')}</span></div><div className="mt-7 flex items-end justify-between"><div><p className="text-xs text-slate-400">{t('progress')}</p><p className="mt-1 text-2xl font-black">{subProgress}%</p></div><BusFront className="text-route" size={34} /></div></div></div><div className="mt-7 h-2 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-route transition-all" style={{ width: `${subProgress}%` }} /></div></Card><Card><div className="flex items-center justify-between"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-sky text-ink  "><Bell size={20} /></div><Badge tone={notifications.filter((n) => !n.is_read).length ? 'danger' : 'neutral'}>{notifications.filter((n) => !n.is_read).length} {t('unread')}</Badge></div><p className="mt-5 text-sm font-bold text-slate-500">{t('notifications')}</p><p className="mt-1 text-2xl font-black text-ink ">{notifications.length}</p><Link to="/app/notifications" className="mt-4 inline-block text-sm font-bold text-route">{t('overview')} <ArrowLeft className="inline" size={15} /></Link></Card></div>
    <div className="mt-5 grid gap-5 lg:grid-cols-[1.35fr_.65fr]"><Card><div className="mb-5 flex items-center justify-between"><div><p className="text-xs font-black uppercase tracking-[.16em] text-route">{t('bookings')}</p><h2 className="mt-1 text-xl font-black text-ink ">{t('bookingHistory')}</h2></div><Link className="text-sm font-bold text-route" to="/app/bookings">{t('allBookings')} <ArrowLeft className="inline" size={15} /></Link></div>{bookings.length ? <div className="space-y-3">{bookings.slice(0, 4).map((booking) => <BookingRow key={booking.id} booking={booking} t={t} language={language} />)}</div> : <EmptyState icon={Ticket} title={t('noBookings')} text={t('bookBlocked')} />}</Card><Card><p className="text-xs font-black uppercase tracking-[.16em] text-route">{t('bookingRules')}</p><div className="mt-5 space-y-4"><Rule icon={<Check size={17} />} text={t('bookingRules')} /><Rule icon={<Clock3 size={17} />} text={`${t('ends')} ${subscription ? formatDate(subscription.end_date, language) : '—'}`} /><Rule icon={<ShieldCheck size={17} />} text={profile.student_id} /></div></Card></div>
  </div>
}
function Rule({ icon, text }: { icon: ReactNode; text: string }) { return <div className="flex items-start gap-3 text-sm font-semibold text-slate-600 "><div className="grid h-8 w-8 shrink-0 place-items-center rounded-xl bg-sky text-ink  ">{icon}</div><span className="pt-1">{text}</span></div> }
function BookingRow({ booking, t, language, onCancel }: { booking: Booking; t: any; language: Language; onCancel?: (id: string) => void }) { return <div className="flex flex-col gap-3 rounded-2xl bg-slate-50 p-4  sm:flex-row sm:items-center"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-white text-route shadow-sm "><BusFront size={18} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-black text-ink ">{booking.station?.name_ar || booking.station_id}</p><StatusBadge value={booking.status} t={t} /></div><p className="mt-1 text-xs font-semibold text-slate-500">{formatDate(booking.service_date, language)} · {booking.departure_time}</p></div>{onCancel && booking.status === 'confirmed' && <Button variant="danger" className="min-h-9 px-3 text-xs" onClick={() => onCancel(booking.id)}><X size={15} /> {t('cancel')}</Button>}</div> }

function NewBookingPage({ profile, t, language }: { profile: Profile; t: any; language: Language }) {
  const navigate = useNavigate(); const [stations, setStations] = useState<Station[]>([]); const [times, setTimes] = useState<DepartureTime[]>([]); const [subscription, setSubscription] = useState<Subscription | null>(null); const [hours, setHours] = useState<BookingHours>({ openTime: '08:00', closeTime: '22:00' }); const [subscriptionLoading, setSubscriptionLoading] = useState(true); const [stationId, setStationId] = useState(profile.default_station_id || ''); const [timeId, setTimeId] = useState(''); const [dateDraft, setDateDraft] = useState(''); const [dates, setDates] = useState<string[]>([]); const [reason, setReason] = useState(''); const [busy, setBusy] = useState(false); const [success, setSuccess] = useState(false); const [requestSent, setRequestSent] = useState(false); const [error, setError] = useState('')
  useEffect(() => { void Promise.all([listActiveStations(), listDepartureTimes(), getBookingHours()]).then(([s, d, bookingHours]) => { setStations(s); setTimes(d); setTimeId(d[0]?.id || ''); setHours(bookingHours) }).finally(() => setSubscriptionLoading(false)) }, [])
  useEffect(() => { void getSubscription(profile.id).then(setSubscription).finally(() => setSubscriptionLoading(false)) }, [profile.id])
  function addDate() { if (dateDraft && dateDraft >= todayISO() && !dates.includes(dateDraft)) { setDates([...dates, dateDraft].sort()); setDateDraft('') } }
  const preferredDays = profile.preferred_weekdays?.length ? profile.preferred_weekdays : [0, 1, 2, 3, 4, 5, 6]
  const offScheduleDates = dates.filter((date) => !preferredDays.includes(new Date(`${date}T00:00:00`).getDay()))
  async function confirm() {
    if (!stationId || !timeId || !dates.length) { setError(t('required')); return }
    if (!isBookingOpen(hours)) { setError(t('bookingClosed')); return }
    setBusy(true); setError('')
    try {
      const regularDates = dates.filter((date) => !offScheduleDates.includes(date))
      if (regularDates.length) await createBookingBatch({ stationId, departureTimeId: timeId, dates: regularDates }, profile.id)
      if (offScheduleDates.length) { for (const date of offScheduleDates) await createBookingChangeRequest({ date, stationId, departureTimeId: timeId, reason }, profile.id); setRequestSent(true) }
      setSuccess(true)
    } catch (err: any) { setError(err?.message === 'BOOKING_DUPLICATE_DATE' ? t('bookingErrorDuplicate') : err?.message === 'BOOKING_CAPACITY_FULL' ? t('bookingErrorCapacity') : err?.message === 'BOOKING_HOURS_CLOSED' ? t('bookingClosed') : err?.message === 'DATE_NOT_IN_SCHEDULE' ? t('scheduleHint') : err?.message === 'REQUEST_ALREADY_EXISTS' ? t('genericError') : t('genericError')) } finally { setBusy(false) }
  }
  if (subscriptionLoading) return <LoadingState />
  const canBook = profile.account_status !== 'suspended' && !!subscription && subscription.status === 'active' && daysLeft(subscription.end_date) > 0 && isBookingOpen(hours)
  if (!canBook) return <div className="animate-rise mx-auto max-w-2xl"><BookingHoursBanner hours={hours} t={t} language={language} /><Card className="border-amber/30 bg-amber-50/70 "><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 text-amber-600" size={24} /><div><h1 className="text-xl font-black text-ink ">{t('bookBlocked')}</h1><p className="mt-2 text-sm leading-7 text-slate-600 ">{!isBookingOpen(hours) ? t('bookingClosed') : profile.account_status === 'suspended' ? t('suspendedMessage') : t('noSubscription')}</p><Button className="mt-5" onClick={() => navigate('/app')}>{t('dashboard')}</Button></div></div></Card></div>
  if (success) return <div className="animate-pop mx-auto max-w-2xl"><Card className="ios-card text-center"><div className="mx-auto grid h-20 w-20 place-items-center rounded-full bg-route text-white"><Check size={38} /></div><h1 className="mt-7 text-3xl font-black text-ink ">{requestSent ? t('requestSent') : t('bookingSuccess')}</h1><p className="mx-auto mt-3 max-w-md text-slate-500">{dates.length} {t('daysSelected')} · {formatDate(dates[0], language)}{dates.length > 1 ? ` + ${dates.length - 1}` : ''}</p><div className="mt-8 flex flex-col justify-center gap-3 sm:flex-row"><Button variant="soft" onClick={() => navigate('/app/bookings')}>{t('bookings')}</Button><Button variant="outline" onClick={() => { setSuccess(false); setRequestSent(false); setDates([]); setReason('') }}>{t('newBooking')}</Button></div></Card></div>
  return <div className="animate-rise"><PageTitle title={t('newBooking')} /><BookingHoursBanner hours={hours} t={t} language={language} /><div className="grid gap-5 lg:grid-cols-[1fr_.8fr]"><Card><div className="mb-6 flex items-center gap-3"><Step n="1" active={!!stationId} /><div className="h-px flex-1 bg-slate-200 " /><Step n="2" active={!!timeId} /><div className="h-px flex-1 bg-slate-200 " /><Step n="3" active={dates.length > 0} /></div><div className="space-y-5"><SelectField label={t('station')} value={stationId} onChange={setStationId} options={stations.map((station) => [station.id, station.name_ar])} required /><SelectField label={t('departure')} value={timeId} onChange={setTimeId} options={times.map((time) => [time.id, time.label || time.time.slice(0, 5)])} required /><div><label className="block"><span className="mb-1.5 block text-sm font-bold text-slate-600 ">{t('selectDates')}</span><div className="flex gap-2"><input className="h-12 min-w-0 flex-1 rounded-2xl border border-slate-200 bg-white px-4 text-sm   " type="date" min={todayISO()} value={dateDraft} onChange={(e) => setDateDraft(e.target.value)} /><Button type="button" variant="soft" onClick={addDate}><Plus size={17} /> {t('add')}</Button></div></label>{dates.length > 0 && <div className="mt-3 flex flex-wrap gap-2">{dates.map((date) => <button type="button" key={date} onClick={() => setDates(dates.filter((item) => item !== date))} className={cx('inline-flex items-center gap-2 rounded-xl px-3 py-2 text-xs font-bold', offScheduleDates.includes(date) ? 'bg-amber-100 text-amber-800' : 'bg-sky text-ink  ')}>{formatDate(date, language)} {offScheduleDates.includes(date) && '· طلب'} <X size={14} /></button>)}</div>}</div>{offScheduleDates.length > 0 && <div className="space-y-3 rounded-2xl bg-amber-50 p-4 "><p className="text-sm font-bold text-amber-800 ">{t('scheduleHint')}</p><Field label={t('requestReason')} value={reason} onChange={setReason} placeholder={t('requestReason')} /></div>}{error && <div className="rounded-2xl bg-rose-50 p-3 text-sm font-bold text-rose">{error}</div>}<Button className="ios-primary w-full" onClick={() => void confirm()} disabled={busy || !dates.length}>{busy ? t('loading') : offScheduleDates.length ? t('sendRequest') : t('confirm')} <Check size={18} /></Button></div></Card><Card className="h-fit"><p className="text-sm font-bold text-slate-500">{t('preferredWeekdays')}</p><div className="mt-4 flex flex-wrap gap-2">{preferredDays.map((day) => <span key={day} className="ios-chip-active rounded-xl px-3 py-2 text-xs font-bold">{t((['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'] as const)[day])}</span>)}</div><div className="mt-6 space-y-4"><SummaryRow icon={<MapPinIcon />} label={t('station')} value={stations.find((s) => s.id === stationId)?.name_ar || '—'} /><SummaryRow icon={<Clock3 size={17} />} label={t('departure')} value={times.find((time) => time.id === timeId)?.label || '—'} /><SummaryRow icon={<CalendarDays size={17} />} label={t('dates')} value={`${dates.length} ${t('daysSelected')}`} /></div></Card></div></div>
}
function Step({ n, active }: { n: string; active: boolean }) { return <div className={cx('grid h-9 w-9 place-items-center rounded-xl text-sm font-black', active ? 'bg-route text-white' : 'bg-slate-100 text-slate-400 ')}>{n}</div> }
function SummaryRow({ icon, label, value }: { icon: ReactNode; label: string; value: string }) { return <div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-sky text-ink  ">{icon}</div><div><p className="text-xs font-semibold text-slate-400">{label}</p><p className="font-black text-ink ">{value}</p></div></div> }

function BookingsPage({ profile, t, language }: { profile: Profile; t: any; language: Language }) {
  const [bookings, setBookings] = useState<Booking[]>([])
  const [subscription, setSubscription] = useState<Subscription | null>(null)
  const [hours, setHours] = useState<BookingHours>({ openTime: '08:00', closeTime: '22:00' })
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  useEffect(() => { void Promise.all([listBookings(profile.id), getSubscription(profile.id), getBookingHours()]).then(([items, currentSubscription, bookingHours]) => { setBookings(items); setSubscription(currentSubscription); setHours(bookingHours) }).finally(() => setLoading(false)) }, [profile.id])
  const canBook = profile.account_status !== 'suspended' && !!subscription && subscription.status === 'active' && daysLeft(subscription.end_date) > 0 && isBookingOpen(hours)
  async function remove(id: string) { setError(''); try { await cancelBooking(id); setBookings((items) => items.map((item) => item.id === id ? { ...item, status: 'cancelled' } : item)) } catch (err: any) { setError(err?.message === 'CANCELLATION_CUTOFF' ? t('cancellationCutoff') : t('genericError')) } }
  return <div className="animate-rise"><PageTitle eyebrow={t('bookings')} title={t('bookingHistory')} action={canBook && <Link to="/app/bookings/new"><Button><Plus size={18} /> {t('newBooking')}</Button></Link>} /><BookingHoursBanner hours={hours} t={t} language={language} />{error && <div className="mb-4 rounded-2xl bg-rose-50 p-3 text-sm font-bold text-rose">{error}</div>}{loading ? <LoadingState /> : bookings.length ? <Card><div className="space-y-3">{bookings.map((booking) => <BookingRow key={booking.id} booking={booking} t={t} language={language} onCancel={remove} />)}</div></Card> : <EmptyState icon={Ticket} title={t('noBookings')} />}</div>
}
function ProfilePage({ profile, t, onProfileChange }: { profile: Profile; t: any; onProfileChange: (profile: Profile) => void }) {
  const [name, setName] = useState(profile.full_name)
  const [studentId, setStudentId] = useState(profile.student_id)
  const [phone, setPhone] = useState(profile.phone)
  const [university, setUniversity] = useState(profile.university || '')
  const [busy, setBusy] = useState(false)
  const [saved, setSaved] = useState(false)
  async function save() {
    setBusy(true)
    await updateOwnProfile(profile.id, { full_name: name, phone, university, default_station_id: profile.default_station_id, student_id: profile.student_id })
    onProfileChange({ ...profile, full_name: name, student_id: profile.student_id, phone, university })
    setSaved(true); setBusy(false); setTimeout(() => setSaved(false), 2500)
  }
  return <div className="animate-rise"><PageTitle eyebrow={t('profile')} title={profile.full_name} text={profile.email} /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><Card><div className="mx-auto grid h-24 w-24 place-items-center rounded-[2rem] bg-route text-3xl font-black text-white">{profile.full_name.slice(0, 1)}</div><div className="mt-5 text-center"><h2 className="text-xl font-black text-ink ">{profile.full_name}</h2><p className="mt-1 text-sm text-slate-500">{profile.student_id}</p><div className="mt-4"><StatusBadge value={profile.account_status} t={t} /></div></div><div className="mt-7 space-y-3 border-t border-slate-100 pt-5 text-sm "><SummaryRow icon={<ShieldCheck size={17} />} label={t('accountStatus')} value={statusLabel(t, profile.account_status)} /><SummaryRow icon={<UsersRound size={17} />} label={t('university')} value={profile.university || '—'} /></div></Card><Card><h2 className="text-xl font-black text-ink ">{t('settings')}</h2><p className="mt-1 text-sm text-slate-500">تحديث البيانات المسموح بها</p><div className="mt-6 space-y-4"><Field label={t('fullName')} value={name} onChange={setName} /><Field label={t('studentId')} value={studentId} onChange={setStudentId} disabled={profile.account_status === 'approved'} /><Field label={t('phone')} value={phone} onChange={setPhone} dir="ltr" /><Field label={t('university')} value={university} onChange={setUniversity} /><p className="-mt-2 text-xs font-semibold text-slate-400">{'يمكنك تحديث بياناتك المسموح بها.'}</p><Button onClick={() => void save()} disabled={busy}>{saved ? <Check size={17} /> : null}{saved ? 'تم الحفظ' : t('save')}</Button></div></Card></div></div>
}
function NotificationsPage({ profile, t, language }: { profile: Profile; t: any; language: Language }) { const [items, setItems] = useState<AppNotification[]>([]); useEffect(() => { void listNotifications(profile.id).then(setItems) }, [profile.id]); async function read(id: string) { await markNotificationRead(id); setItems((list) => list.map((item) => item.id === id ? { ...item, is_read: true } : item)) } return <div className="animate-rise"><PageTitle eyebrow={t('notifications')} title={t('notifications')} text={`${items.filter((item) => !item.is_read).length} ${t('unread')}`} />{items.length ? <div className="space-y-3">{items.map((item) => <Card key={item.id} className={cx('transition', !item.is_read && 'border-route/30 bg-sky/30 ')}><div className="flex items-start gap-4"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-sky text-ink  "><Bell size={19} /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-black text-ink ">{item.title}</h3>{!item.is_read && <Badge tone="danger">{t('unread')}</Badge>}</div><p className="mt-1 text-sm leading-6 text-slate-500">{item.body}</p><p className="mt-3 text-xs font-semibold text-slate-400">{new Intl.DateTimeFormat(language === 'ar' ? 'ar-EG' : 'en-GB', { dateStyle: 'medium' }).format(new Date(item.created_at))}</p></div>{!item.is_read && <Button variant="ghost" className="min-h-9 px-2 text-xs" onClick={() => void read(item.id)}>{t('markRead')}</Button>}</div></Card>)}</div> : <EmptyState icon={Bell} title={t('noNotifications')} />}</div> }

function AdminDashboard({ t }: { t: any }) {
  const [stats, setStats] = useState<DashboardStats | null>(null)
  useEffect(() => { void getDashboardStats().then(setStats) }, [])
  if (!stats) return <LoadingState />
  return <div className="animate-rise"><PageTitle title={t('dashboard')} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard to="/admin/students" icon={UsersRound} label={t('totalStudents')} value={stats.totalStudents} /><StatCard to="/admin/students?status=pending" icon={Clock3} label={t('pendingStudents')} value={stats.pendingStudents} tone="amber" /><StatCard to="/admin/subscriptions?status=active" icon={CalendarDays} label={t('activeSubscriptions')} value={stats.activeSubscriptions} tone="route" /><StatCard to="/admin/subscriptions?status=expiring" icon={Bell} label={t('expiringSubscriptions')} value={stats.expiringSubscriptions} tone="amber" /><StatCard to="/admin/subscriptions?status=expired" icon={X} label={t('expiredSubscriptions')} value={stats.expiredSubscriptions} tone="rose" /><StatCard to="/admin/bookings" icon={Ticket} label={t('todayBookings')} value={stats.todayBookings} /><StatCard to="/admin/bookings" icon={Ticket} label={t('tomorrowBookings')} value={stats.tomorrowBookings} /><StatCard to="/admin/bookings" icon={BusFront} label={t('todayPassengers')} value={`${stats.todayPassengers}/${stats.tripCapacity}`} tone="ink" /></div><div className="mt-5 grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><Card><div className="grid gap-3 sm:grid-cols-2"><QuickAction to="/admin/students" icon={<UsersRound size={18} />} label={t('manageStudents')} /><QuickAction to="/admin/bookings" icon={<ListFilter size={18} />} label={t('manageBookings')} /><QuickAction to="/admin/stations" icon={<MapPinIcon />} label={t('manageStations')} /><QuickAction to="/admin/subscriptions" icon={<CalendarDays size={18} />} label={t('manageSubscriptions')} /><QuickAction to="/admin/requests" icon={<Clock3 size={18} />} label={t('scheduleRequests')} /></div></Card><Card className="route-grid"><div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-route text-white"><BusFront size={21} /></div><div><p className="font-black text-ink ">{t('stationBookings')}</p><p className="text-sm text-slate-500">{t('studentsAtStation')}</p></div></div><div className="mt-6 h-3 overflow-hidden rounded-full bg-slate-200 "><div className="h-full rounded-full bg-route" style={{ width: `${Math.min(100, stats.todayPassengers / Math.max(1, stats.tripCapacity) * 100)}%` }} /></div><div className="mt-3 flex justify-between text-xs font-bold text-slate-500"><span>{stats.todayPassengers} {t('passengers')}</span><span>{Math.round(stats.todayPassengers / Math.max(1, stats.tripCapacity) * 100)}%</span></div></Card></div></div>
}

function QuickAction({ to, icon, label }: { to: string; icon: ReactNode; label: string }) { return <Link to={to} className="flex items-center gap-3 rounded-2xl border border-slate-200 p-3 text-sm font-bold text-ink transition hover:-translate-y-0.5 hover:border-route  "><span className="grid h-9 w-9 place-items-center rounded-xl bg-sky text-ink  ">{icon}</span>{label}<ArrowLeft className="ms-auto" size={16} /></Link> }

function AdminBookingsPage({ t, language }: { t: any; language: Language }) {
  const [bookings, setBookings] = useState<Booking[]>([])
  const [date, setDate] = useState(todayISO())
  const [timeValue, setTimeValue] = useState('')
  const [stationValue, setStationValue] = useState('')
  const [statusValue, setStatusValue] = useState('active')
  const [times, setTimes] = useState<DepartureTime[]>([])
  const [stations, setStations] = useState<Station[]>([])
  const [loading, setLoading] = useState(true)
  const [query, setQuery] = useState('')
  useEffect(() => { void Promise.all([listBookings(undefined, true), listDepartureTimesAdmin(), listStationsAdmin()]).then(([items, departureTimes, stationItems]) => { setBookings(items); setTimes(departureTimes); setStations(stationItems) }).finally(() => setLoading(false)) }, [])
  const filtered = useMemo(() => bookings.filter((booking) => {
    const matchesStatus = statusValue === 'all' || (statusValue === 'active' ? booking.status === 'confirmed' : booking.status === statusValue)
    return (!date || booking.service_date === date) && (!timeValue || booking.departure_time === timeValue) && (!stationValue || booking.station_id === stationValue) && matchesStatus && (!query || `${booking.profile?.full_name} ${booking.profile?.student_id} ${booking.profile?.phone}`.toLowerCase().includes(query.toLowerCase()))
  }), [bookings, date, timeValue, stationValue, statusValue, query])
  const stationGroups = useMemo(() => {
    const map = new Map<string, { station: Station; bookings: Booking[] }>()
    filtered.forEach((booking) => {
      const station = booking.station || stations.find((item) => item.id === booking.station_id) || { id: booking.station_id, name_ar: booking.station_id, name_en: null, sort_order: 999, is_active: true }
      const current = map.get(station.id) || { station, bookings: [] }
      map.set(station.id, { ...current, bookings: [...current.bookings, booking] })
    })
    return [...map.values()].sort((a, b) => a.station.sort_order - b.station.sort_order)
  }, [filtered, stations])
  function stationDetailsUrl(stationId: string) { const params = new URLSearchParams({ date, status: statusValue }); if (timeValue) params.set('time', timeValue); if (query) params.set('q', query); return `/admin/bookings/station/${stationId}?${params.toString()}` }
  function download() { const header = ['Date', 'Time', 'Station', 'Student Name', 'Student ID', 'Phone', 'Status']; const rows = filtered.map((booking) => [booking.service_date, booking.departure_time, booking.station?.name_ar || booking.station_id, booking.profile?.full_name || '', booking.profile?.student_id || '', booking.profile?.phone || '', statusLabel(t, booking.status)]); const csv = [header, ...rows].map((row) => row.map((value) => `"${String(value).replaceAll('"', '""')}"`).join(',')).join('\n'); const blob = new Blob([`\ufeff${csv}`], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `el-saidy-${date || 'bookings'}.csv`; anchor.click(); URL.revokeObjectURL(url) }
  return <div className="animate-rise"><PageTitle eyebrow={t('adminBookings')} title={t('adminBookings')} text="التاريخ ثم الموعد ثم المحطة ثم الطلاب" action={<div className="flex gap-2"><Button variant="outline" onClick={() => window.print()}><FileText size={17} /> {t('print')}</Button><Button onClick={download}><Download size={17} /> {t('exportCsv')}</Button></div>} /><Card className="mb-5"><div className="grid gap-3 md:grid-cols-[.8fr_1fr_1fr_1fr_1.3fr_auto]"><Field label={t('date')} value={date} onChange={setDate} type="date" /><SelectField label={t('departure')} value={timeValue} onChange={setTimeValue} options={times.map((time) => [time.time, time.label || time.time.slice(0, 5)])} /><SelectField label={t('station')} value={stationValue} onChange={setStationValue} options={stations.map((station) => [station.id, station.name_ar])} /><SelectField label={t('status')} value={statusValue} onChange={setStatusValue} options={['active', 'all', 'cancelled', 'boarded', 'no_show'].map((value) => [value, value === 'active' ? t('active') : value === 'all' ? t('all') : statusLabel(t, value)])} /><Field label={t('search')} value={query} onChange={setQuery} placeholder={`${t('studentName')} / ${t('studentId')}`} /><div className="flex items-end"><Badge tone="info"><Filter size={15} /> {filtered.length} {t('passengers')}</Badge></div></div></Card>{loading ? <LoadingState /> : stationGroups.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{stationGroups.map((group) => <Link key={group.station.id} to={stationDetailsUrl(group.station.id)} className="group block rounded-[1.5rem] text-start transition hover:-translate-y-1 focus-visible:ring-2 focus-visible:ring-route"><Card className="h-full cursor-pointer transition group-hover:border-route group-hover:shadow-lift"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-[.14em] text-route">{t('station')}</p><h2 className="mt-2 text-lg font-black text-ink">{group.station.name_ar}</h2></div><div className="grid h-11 w-11 place-items-center rounded-2xl bg-sky text-ink"><BusFront size={19} /></div></div><div className="mt-5 flex items-end justify-between"><span className="text-3xl font-black tabular text-ink">{group.bookings.length}</span><span className="text-sm font-bold text-slate-500">{t('studentsAtStation')}</span></div><p className="mt-3 text-xs font-semibold text-route">{t('viewStudents')} <ArrowLeft className="inline" size={14} /></p></Card></Link>)}</div> : <EmptyState icon={ListFilter} title={t('noData')} />}</div>
}

